#endif /* defined( HAVE_WIDE_CHARACTER_TYPE ) */

int libfvde_internal_volume_open_physical_volume_file_io_handle(
     libfvde_internal_volume_t *internal_volume,
     libbfio_pool_t *file_io_pool,
