					libcerror_error_set(
					 error,
					 LIBCERROR_ERROR_DOMAIN_RUNTIME,
					 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
					 "%s: unable to determine recovery password key.",
					 function );

					goto on_error;
				}
			}
#if defined( HAVE_DEBUG_OUTPUT )
			if( libcnotify_verbose != 0 )
			{
				libcnotify_printf(
				 "%s: passphrase key:\n",
				 function );
				libcnotify_print_data(
				 passphrase_key,
				 16,
				 0 );
			}
#endif
			byte_stream_copy_to_uint32_little_endian(
			 &( passphrase_wrapped_kek[ 24 ] ),
			 value_type );

			byte_stream_copy_to_uint32_little_endian(
			 &( passphrase_wrapped_kek[ 28 ] ),
			 value_size );

#if defined( HAVE_DEBUG_OUTPUT )
			if( libcnotify_verbose != 0 )
			{
				libcnotify_printf(
				 "%s: value type\t\t: 0x%08" PRIx32 "\n",
				 function,
				 value_type );

				libcnotify_printf(
				 "%s: value size\t\t: %" PRIu32 "\n",
				 function,
				 value_size );
			}
#endif
			if( value_type != 0x00000010UL )
			{
				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_RUNTIME,
				 LIBCERROR_RUNTIME_ERROR_UNSUPPORTED_VALUE,
				 "%s: unsupported value type.",
				 function );

				goto on_error;
			}
			if( value_size != 24 )
			{
				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_RUNTIME,
				 LIBCERROR_RUNTIME_ERROR_UNSUPPORTED_VALUE,
				 "%s: unsupported value size.",
				 function );

				goto on_error;
			}
#if defined( HAVE_DEBUG_OUTPUT )
			if( libcnotify_verbose != 0 )
			{
				libcnotify_printf(
				 "%s: encrypted volume key wrapped KEK:\n",
				 function );
				libcnotify_print_data(
				 &( passphrase_wrapped_kek[ 32 ] ),
				 value_size,
				 0 );
			}
#endif
			if( libfvde_encryption_aes_key_unwrap(
			     passphrase_key,
			     16 * 8,
			     &( passphrase_wrapped_kek[ 32 ] ),
			     value_size,
			     volume_key_wrapped_kek,
			     24,
			     error ) == -1 )
			{
				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_RUNTIME,
				 LIBCERROR_RUNTIME_ERROR_GENERIC,
				 "%s: unable to retrieve volume key wrapped KEK.",
				 function );

				goto on_error;
			}
			if( memory_set(
			     passphrase_key,
			     0,
			     16 ) == NULL )
			{
				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_MEMORY,
				 LIBCERROR_MEMORY_ERROR_SET_FAILED,
				 "%s: unable to clear passphrase key.",
				 function );

