				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_RUNTIME,
				 LIBCERROR_RUNTIME_ERROR_VALUE_MISSING,
				 "%s: missing passphrase wrapped KEK: %d.",
				 function,
				 passphrase_wrapped_kek_index );

				goto on_error;
			}
			if( passphrase_wrapped_kek_size != 284 )
			{
				libcerror_error_set(
				 error,
