				 LIBCERROR_RUNTIME_ERROR_VALUE_OUT_OF_BOUNDS,
				 "%s: invalid passphrase wrapped KEK: %d size value out of bounds.",
				 function,
				 passphrase_wrapped_kek_index );

				goto on_error;
			}
			byte_stream_copy_to_uint32_little_endian(
			 &( passphrase_wrapped_kek[ 0 ] ),
