+ * Returns 1 if successful, 0 if not or -1 on error
+ */
+int fvde_test_encrypted_metadata_read_fixture(
+     const char *filename,
+     uint8_t **data,
+     size_t *data_size )
+{
+	char fallback_path[ 256 ];
+
+	FILE *file_stream = NULL;
+	long file_size    = 0;
+	size_t filename_length = 0;
+
+	if( filename == NULL )
+	{
+		return( -1 );
+	}
+	if( data == NULL )
+	{
+		return( -1 );
+	}
+	if( *data != NULL )
+	{
+		return( -1 );
+	}
+	if( data_size == NULL )
+	{
+		return( -1 );
+	}
+	file_stream = file_stream_open(
+	               filename,
+	               FILE_STREAM_BINARY_OPEN_READ );
+
+	if( file_stream == NULL )
+	{
+		filename_length = narrow_string_length(
+		                   filename );
+
+		if( filename_length > ( sizeof( fallback_path ) - 7 ) )
+		{
+			return( -1 );
+		}
+		narrow_string_copy(
+		 fallback_path,
+		 "tests/",
+		 6 );
+
+		narrow_string_copy(
+		 &( fallback_path[ 6 ] ),
+		 filename,
+		 filename_length + 1 );
+
+		file_stream = file_stream_open(
+		               fallback_path,
+		               FILE_STREAM_BINARY_OPEN_READ );
+	}
+	if( file_stream == NULL )
+	{
+		return( -1 );
+	}
+	if( fseek(
+	     file_stream,
+	     0,
+	     SEEK_END ) != 0 )
+	{
+		goto on_error;
+	}
+	file_size = ftell(
+	             file_stream );
+
+	if( file_size <= 0 )
+	{
+		goto on_error;
+	}
+	if( fseek(
+	     file_stream,
+	     0,
+	     SEEK_SET ) != 0 )
+	{
+		goto on_error;
+	}
+	*data = (uint8_t *) malloc(
+	                     sizeof( uint8_t ) * ( file_size + 1 ) );
+
+	if( *data == NULL )
+	{
+		goto on_error;
+	}
+	if( file_stream_read(
+	     file_stream,
+	     *data,
+	     (size_t) file_size ) != (size_t) file_size )
+	{
+		goto on_error;
+	}
+	( *data )[ file_size ] = 0;
+
+	*data_size = (size_t) file_size;
+
+	file_stream_close(
+	 file_stream );
+
+	return( 1 );
+
+on_error:
+	if( *data != NULL )
+	{
+		free(
+		 *data );
+
+		*data = NULL;
+	}
+	if( file_stream != NULL )
+	{
+		file_stream_close(
+		 file_stream );
+	}
+	return( -1 );
